test_compare_float()
{
  TEST_CHECK( gkyl_compare_float(1.0f, 1.0f, 1e-6f) );
  TEST_CHECK( !gkyl_compare_float(1.0f, 2.0f, 1e-6f) );
  TEST_CHECK( gkyl_compare_float(0.0f, 0.0f, 1e-6f) );
  TEST_CHECK( gkyl_compare_float(100.0f, 100.0f, 1e-6f) );
